insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('welltest', 'intermediate', 'module', 'm01-the-derivative', 1, 'Why does differentiating pressure with respect to the logarithm of time help?', '["Because differentiation removes the constant offset that the skin contributes to the pressure.", "Because radial flow becomes a flat line, and the eye reads flat far more reliably than it reads straight.", "Because it converts the semilog plot into a log-log plot, on which every flow regime becomes a straight line.", "Because the derivative is less sensitive to gauge noise than the pressure itself."]'::jsonb, 1, 'A one percent tilt in a horizontal line is visible; a one percent change in the slope of a rising curve is not. That is the entire argument, and it is sufficient.'),
  ('welltest', 'intermediate', 'module', 'm01-the-derivative', 2, 'What value does the derivative take during infinite-acting radial flow?', '["162.6 q B mu divided by k h, the same constant as the semilog slope, since the plots share an axis.", "Zero, because the derivative of a constant is zero and the pressure has stabilised.", "70.6 q B mu divided by k h, which is exactly half the semilog slope.", "It depends on the storage coefficient as well, which is why the plateau cannot be read as a permeability."]'::jsonb, 2, 'Differentiating a base-ten logarithmic line with respect to a natural logarithm divides by ln 10, and 162.6 over 2.303 is 70.6. So the plateau height IS a permeability reading.'),
  ('welltest', 'intermediate', 'module', 'm01-the-derivative', 3, 'For this reservoir at the planted 85 mD, where does the radial plateau sit?', '["At 9.344117647058821 psi.", "At 21.520588235294117 psi, which is the semilog slope for the same reservoir and rate.", "At 4530.771773811249 psi, which is the flowing pressure at the moment of shut-in.", "It cannot be stated without the storage coefficient, which sets the level of the whole curve."]'::jsonb, 0, 'The theoretical plateau is a fixed number for a given rate, fluid, thickness and permeability. Any measured plateau can be held against it directly.'),
  ('welltest', 'intermediate', 'module', 'm01-the-derivative', 4, 'What does the naive derivative, using immediately adjacent points, do on gauge data?', '["It smooths the response, because adjacent samples are highly correlated in time.", "It underestimates the derivative, because the pressure change between adjacent samples is small.", "It works, provided the sampling rate is high enough to resolve the pressure change.", "It divides a noise-sized numerator by a tiny denominator and returns meaningless scatter."]'::jsonb, 3, 'Do it at every point and the derivative plot is a hedge. That is the problem the Bourdet rule was designed to solve.'),
  ('welltest', 'intermediate', 'module', 'm01-the-derivative', 5, 'What does the Bourdet rule do about that?', '["It fits a straight line through a moving window of points and reports its slope at the centre.", "It takes each neighbour at least L logarithmic cycles away and combines the two one-sided slopes with cross-weights.", "It averages the pressure over a window before differentiating, which suppresses the noise first.", "It computes the derivative in Laplace space, where differentiation is a multiplication."]'::jsonb, 1, 'The cross-weighting, each slope weighted by the opposite gap, is what keeps the estimate centred rather than biased towards the closer neighbour.'),
  ('welltest', 'intermediate', 'module', 'm01-the-derivative', 6, 'What is the accepted range for the smoothing window L?', '["Between 1 and 2 cycles, so that the two neighbours span a full decade on each side.", "Between 0.001 and 0.01 cycles, which is fine enough to preserve every real feature of the response.", "Between 0 and about 0.5 logarithmic cycles, with 0.1 the usual default.", "There is no range: L is set to the sampling interval of the gauge in each particular test."]'::jsonb, 2, 'Above about half a cycle, real features start to be smoothed away. Below that, the trade is between noise and bias, and on gauge data the noise term is far larger.'),
  ('welltest', 'intermediate', 'module', 'm01-the-derivative', 7, 'Sweeping L from 0 to 0.5 on the noise-free drawdown moves the last derivative by less than 0.3 percent. What does that show?', '["That L is a noise parameter rather than an accuracy parameter, since noiseless data give it nothing to do.", "That the derivative is insensitive to smoothing in general, so that any value within the range is acceptable.", "That the fixture has too few points for the smoothing window to have any effect at all.", "That the response is close to a pure logarithm, whose derivative is exactly constant."]'::jsonb, 0, 'It also means that on real data, any sensitivity of the answer to L is telling you about the noise rather than about the reservoir.'),
  ('welltest', 'intermediate', 'module', 'm01-the-derivative', 8, 'Which failure mode of smoothing is the dangerous one?', '["Too little, because a scattered derivative cannot be read and the analysis stalls.", "Too much, because it introduces a systematic bias into the plateau height and therefore the permeability.", "Too little, because the endpoints then fall back to one-sided slopes that are less reliable.", "Too much, because the plot looks better while real features have been rounded away."]'::jsonb, 3, 'A scattered derivative is obvious and nobody reads a result off a hedge. A short radial plateau smoothed into its transitions simply disappears, and the result looks clean.'),
  ('welltest', 'intermediate', 'module', 'm01-the-derivative', 9, 'How do you tell a real feature from a smoothing artefact?', '["Compare the derivative against the semilog slope, since a real feature preserves the 70.6 to 162.6 ratio.", "Sweep L: a real feature barely moves, and one that appears or vanishes with the window is not real.", "Compute the derivative twice with different implementations and keep only what both agree on.", "Check the feature against the model catalog, since only shapes the models produce are real."]'::jsonb, 1, 'The second check is to compare the plateau against 0.434 times the semilog slope in psi per cycle. If the plateau is lower, features have been flattened.'),
  ('welltest', 'intermediate', 'module', 'm01-the-derivative', 10, 'Why does the engine differentiate a buildup against Agarwal equivalent time?', '["Because equivalent time is the only variable on which the Bourdet rule''s log spacing is defined.", "Because it makes the buildup derivative dimensionally consistent with the drawdown''s.", "Because differentiating against raw shut-in time makes the derivative droop late for reasons unrelated to the reservoir.", "Because equivalent time compresses the late data, which reduces the noise in the derivative there."]'::jsonb, 2, 'The same transform is applied to the model and to the data inside autoFitModel, which is essential: a derivative computed differently on the two sides compares two different quantities.'),
  ('welltest', 'intermediate', 'module', 'm01-the-derivative', 11, 'What happens if you pass rows shaped as t and dp to bourdetDerivative without naming the keys?', '["It returns an empty array, because every row is dropped for having no x.", "It throws an error naming the missing field, which is caught by the calling code.", "It differentiates the first two numeric fields it finds, which happens to be correct here.", "It returns the derivative against dp rather than against t, which is visibly wrong on a plot."]'::jsonb, 0, 'Not an error and not a warning. An empty array is exactly what a derivative that could not be computed would also look like, and every downstream consequence is silent.'),
  ('welltest', 'intermediate', 'module', 'm01-the-derivative', 12, 'What is the general shape of that bug?', '["A function that mutates its input leaves the caller holding data that no longer match the call.", "A function with default arguments silently substitutes a value the caller did not intend.", "A function returning null rather than throwing forces every caller to write the same check.", "A function that filters its input rather than validating it treats a misspelled field as an absent value."]'::jsonb, 3, 'The filter is there for good reasons, since real gauge data have gaps and nulls. It cannot distinguish a missing measurement from a programming error.'),
  ('welltest', 'intermediate', 'module', 'm01-the-derivative', 13, 'What is the strongest defence against that class of bug?', '["Passing the key names explicitly on every call, which removes the ambiguity at the call site.", "A test that runs the derivative on a fixture with a known plateau and asserts the height.", "Comparing the input and output lengths, which catches an empty return immediately.", "Wrapping the engine call in a try-catch so that any failure is surfaced to the user."]'::jsonb, 1, 'All three are worth doing and they are listed in increasing order of reliability. The test fails when the wiring breaks rather than when somebody happens to look at a plot.'),
  ('welltest', 'intermediate', 'module', 'm01-the-derivative', 14, 'Why is the derivative''s first or last point less reliable than the ones in the middle?', '["Because the gauge is still settling at the start and drifting by the end of a long test.", "Because the smoothing window is widest at the ends, which averages over more of the transition.", "Because with no neighbour on one side the engine falls back to a one-sided two-point slope.", "Because the endpoints carry the largest pressure changes and therefore the largest absolute errors."]'::jsonb, 2, 'It is why a plateau should not be read off a derivative plot''s extreme points, and the engine will happily return them.'),
  ('welltest', 'intermediate', 'module', 'm01-the-derivative', 15, 'A derivative plateau is read as a MEAN over a window rather than as one point. Why?', '["Because each derivative value carries the noise of two differences, and averaging removes some of it.", "Because the plateau is not exactly flat, so a mean is the best linear estimate of its level.", "Because the engine returns a mean rather than a series, so the caller has no choice.", "Because a single point could fall on a transition, which a mean over a window cannot."]'::jsonb, 0, 'The engine returns the raw series and it is the caller''s job to average. Wherever it matters, this course states the window the mean was taken over.'),
  ('welltest', 'intermediate', 'module', 'm02-reading-shapes', 1, 'Which derivative slope corresponds to linear flow?', '["One quarter, which is what flow into a plane gives once the plane''s own conductivity is finite.", "One half, because the pressure change goes as the square root of time when fluid moves towards a plane.", "One, since a plane geometry gives a pressure change proportional to elapsed time.", "Zero, because linear flow gives a constant pressure gradient and therefore a constant derivative."]'::jsonb, 1, 'A quarter is bilinear flow, which is two linear flows at right angles. A unit slope is storage early or a closed boundary late.'),
  ('welltest', 'intermediate', 'module', 'm02-reading-shapes', 2, 'Why do wellbore storage and a closed boundary share the same derivative slope?', '["Because both are dominated by compressibility rather than by permeability, which sets the slope.", "Because the engine treats a closed boundary as an image well placed at the wellbore.", "Because a unit slope is what the Bourdet rule returns whenever the response is not logarithmic.", "Because both give a pressure change proportional to elapsed time, one from a wellbore and one from a tank."]'::jsonb, 3, 'The engine distinguishes them by position, not by slope: a unit-slope segment that is first becomes wellbore storage and one that is last becomes a boundary.'),
  ('welltest', 'intermediate', 'module', 'm02-reading-shapes', 3, 'Which flow regime always comes first in a test?', '["Wellbore storage, because the wellbore sits between the reservoir and the gauge.", "Radial flow, since the disturbance spreads radially from the moment the rate changes.", "Linear flow, because the first fluid to move is the fluid closest to the sandface.", "It depends on the well: a fractured well shows linear flow before any storage."]'::jsonb, 0, 'Boundaries always come last, because the disturbance has to travel to reach them. Near-well geometry comes early, and radial flow is in the middle when it exists at all.'),
  ('welltest', 'intermediate', 'module', 'm02-reading-shapes', 4, 'A half slope appears BEFORE the radial plateau. What does that indicate?', '["A channel, since parallel boundaries produce linear flow once the disturbance fills the width.", "A constant-pressure boundary that is being approached from one side of the well.", "A fracture, because linear flow towards a fracture face is a near-well geometry effect.", "Nothing, because a half slope before radial flow is not a physically realisable sequence."]'::jsonb, 2, 'A half slope AFTER the plateau is a channel, because the channel walls are far away. Same slope, opposite ends of the test, completely different conclusions.'),
  ('welltest', 'intermediate', 'module', 'm02-reading-shapes', 5, 'How does detectFlowRegimes estimate the local slope?', '["By fitting a straight line to the whole segment once its extent has been determined.", "By central difference on the logarithms over up to two points on each side of the point.", "By differentiating the Bourdet derivative a second time and integrating the result.", "By comparing the derivative against the model catalog''s own asymptotic values at each time."]'::jsonb, 1, 'Then it maps that slope to a label with fixed bands, groups consecutive points with the same label, and discards any segment shorter than a quarter of a decade.'),
  ('welltest', 'intermediate', 'module', 'm02-reading-shapes', 6, 'Which of these is NOT one of the classifier''s ordering rules?', '["A unit slope that is first becomes storage, and one that is last becomes a boundary.", "A constant-pressure stretch with any regime after it becomes a transition instead.", "A bilinear stretch with radial or linear flow before it becomes a transition instead.", "A radial segment must be the longest one reported, since radial flow dominates a good test."]'::jsonb, 3, 'There is no rule about length beyond the quarter-decade minimum span. A short radial plateau between two long regimes is perfectly possible and is reported as radial.'),
  ('welltest', 'intermediate', 'module', 'm02-reading-shapes', 7, 'Why are there gaps between the classifier''s slope bands?', '["So that a slope which is not clearly any regime gets no label at all.", "To avoid double-counting a point that falls on the edge between two adjacent bands.", "Because the bands were fitted to field data and the gaps are where the data were sparse.", "To leave room for regimes the engine does not yet implement, such as spherical flow."]'::jsonb, 0, 'An unlabelled stretch is the classifier saying it does not recognise the shape, which is usually because the shape is a transition. That is a feature.'),
  ('welltest', 'intermediate', 'module', 'm02-reading-shapes', 8, 'What does the quarter-decade minimum span do?', '["It ensures every reported segment contains at least five points, which the slope estimate needs.", "It matches the Bourdet smoothing window, so that no segment is shorter than the derivative''s resolution.", "It stops noise from generating segments, at the cost of hiding a real but short regime.", "It prevents two adjacent segments with the same label from being reported separately."]'::jsonb, 2, 'An absent label is therefore not evidence of an absent regime. On the fracture fixture, radial flow is reported over exactly 0.25 decades at the threshold.'),
  ('welltest', 'intermediate', 'module', 'm02-reading-shapes', 9, 'On the buildup, which has no boundary of any kind, what does the classifier report before radial flow?', '["A constant-pressure boundary, since a steep fall is what the recharge band is defined by.", "Wellbore storage, correctly identified by the rule about a unit slope that comes first.", "A transition, because the slope lands in the recharge band but radial flow follows it.", "Nothing at all, because the storage transition has no slope inside any of the bands."]'::jsonb, 2, 'The storage hump does fall steeply onto the radial plateau and the slope does land in the constant-pressure band. The ordering rule is what stops it being called a boundary: recharge does not recover.'),
  ('welltest', 'intermediate', 'module', 'm02-reading-shapes', 10, 'Why is the sealing fault''s ramp between its two plateaus reported as a transition?', '["Because its slope lands in the bilinear band, and bilinear flow cannot follow radial flow.", "Because it is shorter than a quarter of a decade and therefore fails the minimum span test.", "Because the derivative is noisy in that interval, and noise is never given a regime label.", "Because a segment between two segments carrying the same label is always a transition."]'::jsonb, 0, 'It is longer than the minimum, which is why it survives at all. Bilinear flow is near-well fracture geometry and precedes radial flow, so the ordering rule catches it.'),
  ('welltest', 'intermediate', 'module', 'm02-reading-shapes', 11, 'Which two mechanisms produce every false label on this course''s fixtures?', '["Noise in the derivative, and segments that are shorter than the minimum span.", "Over-smoothing, which flattens features, and under-smoothing, which fragments them.", "A wrong time transform on a buildup, and an incorrect storage coefficient in the model.", "A steep fall between two regimes, and a slow rise between two separated plateaus."]'::jsonb, 3, 'Both are transitions. The first lands in the constant-pressure band and the second in the bilinear band, and both are longer than the minimum span.'),
  ('welltest', 'intermediate', 'module', 'm02-reading-shapes', 12, 'Which false label do the ordering rules NOT remove?', '["The buildup''s storage fall, which the recharge band still claims on an infinite-acting test.", "The horizontal well''s climb to pseudoradial flow, which stays in the bilinear band.", "The sealing fault''s first segment, called linear flow where it is a storage roll-off.", "The dual-porosity dip, which recovers and is therefore still reported as recharge."]'::jsonb, 2, 'A fracture''s linear flow legitimately comes first, and so does the roll-off of a storage unit slope, so nothing about the ORDER separates them. The pressure curve does, and the classifier is not given it.'),
  ('welltest', 'intermediate', 'module', 'm02-reading-shapes', 13, 'What three things does a regime label need before it is a diagnosis?', '["The slope is in the band, the level implies a sensible parameter, and the fit converges on it.", "The slope is in the band, the segment is long enough, and the regime is possible in that position.", "The segment spans at least a decade, contains at least ten points, and has an r squared above 0.99.", "The label agrees with the model catalog, the previous test on the well, and the geological model."]'::jsonb, 1, 'The software supplies the first two. You supply the third, and it needs information the pressure history does not contain.'),
  ('welltest', 'intermediate', 'module', 'm02-reading-shapes', 14, 'What is the height check on a regime label?', '["Compute what the segment''s level implies numerically and ask whether that number is credible for this well.", "Confirm that the derivative level is exactly half the semilog slope over the same interval.", "Check that the level lies between the storage line and the radial plateau of the model.", "Verify that the level has not changed since the previous test on the same well."]'::jsonb, 0, 'A plateau implying 900 mD in a field mapped at 40 is telling you something, and it is not that the reservoir is 900 mD.'),
  ('welltest', 'intermediate', 'module', 'm02-reading-shapes', 15, 'Two different diagnoses both pass the slope, span and ordering checks. What is the right response?', '["Choose the simpler one, since a model with fewer parameters is preferred when both fit.", "Choose the one consistent with the geological model, which is the independent information available.", "Report neither, since an ambiguous diagnosis cannot support a quantitative result.", "Report both of them, and say what additional measurement would separate the two."]'::jsonb, 3, 'Non-uniqueness is a real property of pressure transient data rather than a failure of the method. Picking the one the software listed first is the failure.'),
  ('welltest', 'intermediate', 'module', 'm03-boundaries', 1, 'How does the engine represent a sealing fault?', '["As an identical image well producing at the same rate, mirrored across the fault plane.", "As a reduced permeability zone beyond the fault distance, which slows the transient.", "As a no-flow condition imposed directly on the Laplace-space solution at that fixed radius.", "As a negative image well, so that the two pressure fields cancel on the fault."]'::jsonb, 0, 'A negative image is a constant-pressure boundary. The positive image gives no flow across the plane halfway between the two wells, which is exactly a sealing fault.'),
  ('welltest', 'intermediate', 'module', 'm03-boundaries', 2, 'What does a fully developed sealing fault do to the derivative?', '["Halves it, because the drainage area available to the well is cut in two by the fault.", "Leaves it unchanged but shifts the pressure curve, since a fault adds a constant pressure drop.", "Doubles it, because two wells are now producing where there was one.", "Makes it rise on a half slope, because flow becomes linear along the fault plane."]'::jsonb, 2, 'A half slope is what a CHANNEL gives, once the disturbance has filled the width between two parallel faults.'),
  ('welltest', 'intermediate', 'module', 'm03-boundaries', 3, 'On the fault fixture the derivative reaches only about 1.76 times its early plateau in a thousand hours. Why?', '["Because the fault is partially sealing, so some flow crosses it and limits the doubling.", "Because the image well is at a distance and its logarithmic response takes a very long time to catch up.", "Because the storage transient has not fully died, which suppresses the late derivative.", "Because the derivative was over-smoothed, and smoothing always reduces a feature''s amplitude."]'::jsonb, 1, 'The doubling is asymptotic. Reading a fault distance off the time at which the doubling completes is reading off an event that does not occur.'),
  ('welltest', 'intermediate', 'module', 'm03-boundaries', 4, 'Fitting a semilog line to the fault fixture''s late stretch gives what?', '["About twice the true permeability, because the doubled derivative implies a doubled capacity.", "The correct permeability, since the late data are furthest from the storage transient.", "An unstable answer, because only seven points survive in that window.", "About half the true permeability, and a skin that has gone negative."]'::jsonb, 3, 'The late line has nearly twice the slope, and permeability is inversely proportional to slope. The skin follows it down for the same reasons as in the Associate tier''s window walk.'),
  ('welltest', 'intermediate', 'module', 'm03-boundaries', 5, 'Which of the two semilog lines on the fault fixture should be reported?', '["The early one, because that is the reservoir behaving as the radial equation assumes.", "The late one, because storage has certainly died by then and the fit is cleaner.", "Their average, weighted by the number of points in each, which is the usual convention.", "Neither, because a faulted well cannot be analysed by a semilog method at all."]'::jsonb, 0, 'There is a correction: under a single-fault assumption the true permeability is twice what the late line reports. Knowing it is a single fault is the thing you were trying to establish.'),
  ('welltest', 'intermediate', 'module', 'm03-boundaries', 6, 'What is the same about the storage error and the sealing-fault error?', '["Both arise from fitting too few points, so the least squares estimate becomes unstable.", "Both are caused by the producing time being wrong for the transform being used.", "Both apply the infinite-acting radial equation to data that are not infinite-acting radial flow.", "Both inflate the permeability and reduce the skin, which is the characteristic direction."]'::jsonb, 2, 'The characteristic direction is the opposite: both REDUCE the permeability and reduce the skin. Well test analyses that get the regime wrong understate permeability and overstate stimulation.'),
  ('welltest', 'intermediate', 'module', 'm03-boundaries', 7, 'What does a constant-pressure boundary do to the derivative?', '["Makes it rise on a unit slope, because the reservoir behaves as a tank once the boundary is reached.", "Makes it plunge, because the pressure change is approaching a constant.", "Doubles it, in the same way as a sealing fault but with the opposite sign of image well.", "Flattens it at a lower level, corresponding to the higher effective permeability."]'::jsonb, 1, 'It is the steepest feature in well testing, and it is what the classifier''s constant-pressure band is looking for. It is also what a storage transition imitates.'),
  ('welltest', 'intermediate', 'module', 'm03-boundaries', 8, 'Why is a constant-pressure boundary the most consequential thing a test can find?', '["Because it puts an upper bound on the drainage volume, which reserves calculations depend on.", "Because it means the reservoir pressure can be measured directly rather than extrapolated.", "Because it is the only boundary whose distance can be determined from a single-rate test.", "Because a well with pressure support will keep producing at a rate a depletion forecast does not predict."]'::jsonb, 3, 'The question is not how far away it is but what it is: an aquifer, a gas cap, a nearby injector, or an artefact in the late data. That is why it needs corroboration.'),
  ('welltest', 'intermediate', 'module', 'm03-boundaries', 9, 'A well between two parallel sealing faults shows what at late time?', '["A half slope, because once the disturbance fills the channel width the flow is one dimensional.", "A unit slope, since a channel is bounded and therefore reaches pseudo-steady state.", "A quarter slope, because flow is linear along the channel and radial into it at the very same time.", "A doubled plateau, since each of the two faults contributes an image well."]'::jsonb, 0, 'The half slope late is a channel. The same half slope early is a fracture. The sequence is the only thing that separates them.'),
  ('welltest', 'intermediate', 'module', 'm03-boundaries', 10, 'What does a closed reservoir show once every boundary has been felt?', '["A plateau at a higher level, corresponding to the reduced area available to supply the well.", "A unit slope on the derivative, because the pressure falls linearly in time as the tank depletes.", "A derivative that plunges, since the reservoir can no longer supply any fluid at the rate required.", "A quarter slope, which is the signature of a bounded system approaching equilibrium."]'::jsonb, 1, 'That is pseudo-steady state, and it is the only regime in this course that is about a volume rather than about a rate capacity.'),
  ('welltest', 'intermediate', 'module', 'm03-boundaries', 11, 'Why is the pseudo-steady state equation free of permeability, skin and geometry?', '["Because those quantities are absorbed into the intercept of the Cartesian line rather than its slope.", "Because at pseudo-steady state the pressure gradient is zero everywhere in the drainage volume.", "Because it is a material balance on a closed tank rather than a statement about how pressure spreads.", "Because they cancel between the numerator and the denominator when the equation is made dimensionless."]'::jsonb, 2, 'Every other regime is about a rate. Pseudo-steady state is about how much fluid the tank holds, which is why the answer is a pore volume.'),
  ('welltest', 'intermediate', 'module', 'm03-boundaries', 12, 'The rectangle fixture''s drainage area comes back within a few thousandths of a percent. Why so accurate?', '["Because the Cartesian fit uses eight points, which is enough for the least squares to converge exactly.", "Because the fixture was generated from the same equation the analysis inverts, so it is a tautology.", "Because the boundary distances were chosen so that the transition is short and clean.", "Because pseudo-steady state is an equilibrium rather than an asymptote being approached."]'::jsonb, 3, 'Every other analysis in this course is an extrapolation. There is nothing left to converge towards once the tank is depleting uniformly.'),
  ('welltest', 'intermediate', 'module', 'm03-boundaries', 13, 'Which input dominates the uncertainty in a drainage area from a well test?', '["Total compressibility, because the pore volume is inversely proportional to it.", "The flow rate, which enters the pore volume equation linearly and is often 5 percent uncertain.", "The net pay, since the area is the pore volume divided by porosity times thickness.", "The window, because fitting the transition rather than pseudo-steady state changes the slope."]'::jsonb, 0, 'All four matter and compressibility is the largest lever that comes from entirely outside the test. A ct 20 percent high gives a pore volume 17 percent low, from data that fit the line just as well.'),
  ('welltest', 'intermediate', 'module', 'm03-boundaries', 14, 'What does a drainage volume smaller than the volumetric estimate suggest?', '["That the total compressibility used in the analysis was too low for the fluid present.", "That the well is in a compartment: faults, pinch-outs or facies changes are cutting it off.", "That pseudo-steady state was not reached, so the late line is still steepening.", "That the porosity used to convert the pore volume into an area was too high."]'::jsonb, 1, 'A volume LARGER than the map suggests either more connection than the map gives, a compressibility that was too low, or a transition mistaken for pseudo-steady state.'),
  ('welltest', 'intermediate', 'module', 'm03-boundaries', 15, 'Why should a drainage area from a well test be dated?', '["Because the compressibility of the fluid changes as the reservoir depletes over time.", "Because the analysis is only valid while the reservoir remains above the bubble point.", "Because it is the volume the well is connected to under the current well configuration and rates.", "Because a drainage area is measured in acres, and acreage assignments change with lease boundaries."]'::jsonb, 2, 'Drill an infill well and it changes. Shut in a neighbour and it changes. It is a dynamic quantity rather than a share of the field.'),
  ('welltest', 'intermediate', 'module', 'm04-the-well-itself', 1, 'Why is the fracture fixture in 5 mD rock when everything else in the course is 85?', '["Because the fracture model in the catalog is only valid below about 10 millidarcies.", "Because a fracture only dominates the response when the formation is tight enough for it to matter.", "Because a lower permeability lengthens the test, which is what is needed to reach radial flow at all.", "Because the linear flow regime requires a low diffusivity to be resolvable by a gauge."]'::jsonb, 1, 'Nobody fractures 85 mD rock. The regimes a fracture produces are only visible when the fracture is doing most of the work.'),
  ('welltest', 'intermediate', 'module', 'm04-the-well-itself', 2, 'What does infinite conductivity mean for a fracture?', '["The fracture extends far enough that its tips are never felt during the test.", "The fracture accepts fluid from the formation without any flow restriction at its face.", "The fracture''s permeability is high enough that its own storage is negligible.", "There is no measurable pressure drop along the fracture, so its whole face sits at the wellbore pressure."]'::jsonb, 3, 'That makes the fracture face a plane at constant pressure, and fluid moves towards it perpendicularly from both sides. The finite-conductivity case gives bilinear flow first.'),
  ('welltest', 'intermediate', 'module', 'm04-the-well-itself', 3, 'The classifier reports linear flow over 3.25 decades on the fracture fixture. What does that indicate?', '["A single clean regime spanning more than three decades, which is what a well designed fractured-well test looks like.", "An over-smoothed derivative, since no real regime persists for that long in one test.", "A test that ran far longer than necessary, since a decade is enough to fit a linear-flow line.", "A fracture whose conductivity is finite, since infinite conductivity gives a shorter linear period."]'::jsonb, 0, 'Compare it against the radial flow the classifier reports at the end of the same test: exactly 0.25 decades, which is the minimum span it will report at all.'),
  ('welltest', 'intermediate', 'module', 'm04-the-well-itself', 4, 'What does the sqrt-time line measure on a fractured well?', '["The fracture half-length directly, which is why the analysis needs no other input.", "The fracture conductivity, which is the product of the fracture permeability and its width.", "The product of the fracture half-length and the square root of the permeability.", "The permeability, since the half-length cancels between the slope and the intercept."]'::jsonb, 2, 'Halve the permeability and adjust the half-length and the response is identical. The split needs a permeability from somewhere else, which on this fixture is the late radial plateau.'),
  ('welltest', 'intermediate', 'module', 'm04-the-well-itself', 5, 'Fitting the sqrt-time line from 0.1 to 10 hours gives a half-length about 14 percent high. Why?', '["Because the permeability used in the conversion was the planted one rather than the fitted one.", "Because the window runs past pure linear flow into the transition, which is flatter and lowers the slope.", "Because the earliest points are storage-affected and steepen the fitted line, which raises the half-length.", "Because the sqrt-time fit does not pass through the origin, and the intercept was ignored."]'::jsonb, 1, 'A lower slope gives a longer half-length. Confining the fit to the interval the derivative calls linear flow gives a considerably better answer.'),
  ('welltest', 'intermediate', 'module', 'm04-the-well-itself', 6, 'A semilog analysis of the fracture fixture over 0.1 to 10 hours reports what?', '["About 5 mD and a skin near zero, since the semilog line is valid once linear flow has ended.", "About 1 mD and a large positive skin, because the fracture is read as a restricted entry.", "Nothing, because a semilog fit on data with a half slope fails to converge.", "About 26 mD on rock that is 5 mD, and a skin of about minus 4.4 on a well with none."]'::jsonb, 3, 'It reports a reservoir five times better than it is, and a stimulation that is real but is not a negative skin. Both errors flatter the well.'),
  ('welltest', 'intermediate', 'module', 'm04-the-well-itself', 7, 'Why do the inflated permeability and the negative skin appear together?', '["Because the analysis distributes one physical effect, the fracture, between two parameters that cannot represent it.", "Because a negative skin mathematically requires a higher permeability to keep the pressure drop fixed.", "Because the least squares fit trades the two against each other to minimise the residual.", "Because the fracture increases the effective wellbore radius, which enters both quantities."]'::jsonb, 0, 'Some of the fracture''s effect goes into an inflated permeability and some into a negative skin. Neither number means what its name says.'),
  ('welltest', 'intermediate', 'module', 'm04-the-well-itself', 8, 'When IS the equivalent-skin description of a fractured well valid?', '["At early time, before the fracture tips are felt and the well behaves as a single point source.", "Never, since a fracture and a negative skin have fundamentally different pressure signatures.", "At late time, once the whole fractured region looks like a point to the disturbance.", "Whenever the fracture conductivity is finite, since that limits the stimulation to a skin-like effect."]'::jsonb, 2, 'It is useful for inflow performance calculations. Applying it to the early data, which is what a semilog fit on linear flow does, is what produces the five-times-too-high permeability.'),
  ('welltest', 'intermediate', 'module', 'm04-the-well-itself', 9, 'What are the three regimes a horizontal well shows, in order?', '["Linear flow, then bilinear flow, then radial flow, as with a finite-conductivity fracture.", "Vertical radial flow, then linear flow, then pseudoradial flow.", "Radial flow, then a boundary effect, then pseudo-steady state as the drainage volume closes.", "Wellbore storage, then linear flow, then a doubled derivative from the top and bottom boundaries."]'::jsonb, 1, 'Early flow converges on the lateral in the vertical plane. Once the top and bottom are reached it becomes linear. Eventually the 2000 ft lateral looks like a point and flow is radial in the horizontal plane.'),
  ('welltest', 'intermediate', 'module', 'm04-the-well-itself', 10, 'What do the two plateaus on a horizontal well''s derivative measure?', '["The first involves the geometric mean of horizontal and vertical permeability with the well length; the second is ordinary horizontal permeability with the layer thickness.", "Both measure the horizontal permeability, and their difference is a measure of the anisotropy.", "The first measures the vertical permeability and the second the horizontal, directly.", "The first measures the near-well damage and the second the undamaged reservoir beyond it."]'::jsonb, 0, 'That is why a horizontal well test, if it is long enough, gives both the horizontal permeability and the anisotropy, which a vertical well test cannot.'),
  ('welltest', 'intermediate', 'module', 'm04-the-well-itself', 11, 'What does the classifier report between the linear and pseudoradial flow on the horizontal fixture?', '["Nothing, because the transition''s slope falls in one of the gaps between the bands.", "A constant-pressure segment, because the derivative falls as pseudoradial flow is approached.", "A second linear segment, because the flow remains one dimensional throughout the transition.", "A transition, because the slope lands in the bilinear band and radial flow came before it."]'::jsonb, 3, 'Bilinear flow is a fracture regime and there is no fracture. The ordering rule catches it, which is the same mechanism as on the sealing-fault fixture''s ramp.'),
  ('welltest', 'intermediate', 'module', 'm04-the-well-itself', 12, 'Why does a semilog analysis of a horizontal well''s early data produce a meaningless number?', '["Because the early data are always storage-dominated on any horizontal well, which will have a very large wellbore volume.", "Because the flow is linear rather than radial at early time, so the semilog line has no meaning.", "Because the early plateau involves the well length and the anisotropy, not the layer thickness the equation assumes.", "Because horizontal wells are completed openhole, so the wellbore radius in the equation is undefined."]'::jsonb, 2, 'The quantity the equation computes is not the quantity the equation defines. Fitting the late data instead gives the right horizontal permeability, if pseudoradial flow has been reached.'),
  ('welltest', 'intermediate', 'module', 'm04-the-well-itself', 13, 'What is the effective fracture half-length, as opposed to the propped length?', '["The length of the fracture that remains open once the proppant has settled and the well has been flowed back.", "The length of an idealised planar infinite-conductivity fracture that would give the same pressure response.", "The propped length reduced by the damaged region at the fracture face, which contributes no flow.", "The half-length measured from the wellbore to the tip, which is half the total fracture length."]'::jsonb, 1, 'The propped length is usually longer, sometimes much longer, because the far tips carry little conductivity and contribute little flow. Comparing the effective length against a design''s propped length is a category error.'),
  ('welltest', 'intermediate', 'module', 'm04-the-well-itself', 14, 'A fracture half-length comes back below design. What should be checked before blaming the job?', '["The gauge resolution, since a short linear-flow period is easily lost in the noise.", "The rate record, since the sqrt-time slope is proportional to rate and a rate error scales it.", "The storage coefficient, which shortens the visible linear flow period if it is large.", "The permeability used in the conversion, since the half-length scales with its square root."]'::jsonb, 3, 'A short fracture, a conductive one damaged by gel residue, a fracture into a bounded interval, or simply a permeability assumption that was too low all produce the same result.'),
  ('welltest', 'intermediate', 'module', 'm04-the-well-itself', 15, 'Why does a well in tight rock with a long fracture rarely need a semilog analysis?', '["Because radial flow may occupy a quarter of a decade at the end of a very long test, or never appear at all.", "Because the fracture makes the well behave as though it had a very much larger wellbore, so the skin alone is enough.", "Because the sqrt-time analysis returns the permeability as well, making the semilog line redundant.", "Because tight rock reaches its boundaries quickly, so pseudo-steady state arrives before radial flow."]'::jsonb, 0, 'This is the general situation for unconventional wells. Linear-flow methods and rate transient analysis are what work there, and the semilog line never appears.'),
  ('welltest', 'intermediate', 'module', 'm05-heterogeneity-and-data', 1, 'In the Warren and Root idealisation, what do the fissures do?', '["Hold almost all the fluid while conducting very little of the flow, which the matrix then supplies.", "Provide the storage that the matrix lacks, so that the two systems have comparable capacities.", "Conduct almost all the flow while holding very little of the fluid.", "Connect the matrix blocks to each other, without contributing to the flow towards the well."]'::jsonb, 2, 'The matrix is the reverse: almost all the fluid, almost none of the conduction. Two systems occupying the same space with very different roles.'),
  ('welltest', 'intermediate', 'module', 'm05-heterogeneity-and-data', 2, 'What is the storativity ratio omega?', '["The fraction of the total storage capacity that lives in the fissure system.", "The ratio of fissure permeability to matrix permeability, which sets how fast the matrix can resupply.", "The fraction of the pore volume occupied by the fissures, which is the fracture porosity.", "The ratio of the fissure spacing to the wellbore radius, made dimensionless."]'::jsonb, 0, 'It is a ratio of storage CAPACITIES, which is porosity times compressibility. The fissures are often much more compressible than the matrix, so omega can be several times the porosity ratio.'),
  ('welltest', 'intermediate', 'module', 'm05-heterogeneity-and-data', 3, 'What does the interporosity coefficient lambda measure?', '["How much of the total flow crosses directly from matrix to wellbore without passing through a fissure.", "How readily the matrix gives fluid up to the fissures, carrying the block size and the permeability ratio.", "The time at which the matrix and fissure pressures reach equilibrium, in dimensionless units.", "The fraction of matrix blocks that are connected to the fissure network at all."]'::jsonb, 1, 'It is typically between 1e-4 and 1e-9, and small lambda means slow transfer. Both parameters are needed to describe the pair.'),
  ('welltest', 'intermediate', 'module', 'm05-heterogeneity-and-data', 4, 'Why does the derivative DIP in a dual-porosity reservoir?', '["Because the fissure system depletes completely, leaving a period with no supply at all.", "Because the fissures close as the pressure falls, which reduces the effective permeability.", "Because the transition between the two systems produces a constant-pressure boundary effect.", "Because the matrix starts to feed the fissures, and extra supply slows the pressure decline."]'::jsonb, 3, 'A slowing decline is a falling derivative. The dip recovers once the two systems are in equilibrium, which is what distinguishes it from a real recharge boundary.'),
  ('welltest', 'intermediate', 'module', 'm05-heterogeneity-and-data', 5, 'Why do the early and late plateaus sit at the same level in the ideal case?', '["Because the permeability itself has not changed; only the storage available to the well has.", "Because both plateaus are read at the same time on the log-log plot after normalisation.", "Because the matrix permeability is negligible, so the total system permeability equals the fissure''s.", "Because the Bourdet window averages across the dip and returns both plateaus at the mean level."]'::jsonb, 0, 'Two plateaus at the same height with a dip between them is the signature, and nothing else in well testing looks like it.'),
  ('welltest', 'intermediate', 'module', 'm05-heterogeneity-and-data', 6, 'On this fixture the early plateau is HIGHER than the late one. Why?', '["Because the fissure permeability is genuinely higher than the total system permeability.", "Because wellbore storage is still dying at those times, so the early plateau is a mixture rather than a clean fissure response.", "Because the derivative was computed against elapsed time rather than against equivalent time.", "Because the classifier averages the early plateau over a window that includes the unit slope."]'::jsonb, 1, 'That is the ordinary situation on real dual-porosity tests: the early plateau is usually the first casualty of storage, and the dip and the late plateau are what you actually get.'),
  ('welltest', 'intermediate', 'module', 'm05-heterogeneity-and-data', 7, 'How do you tell a dual-porosity dip from a constant-pressure boundary?', '["Measure the depth: a dip is always shallower than a recharge boundary''s derivative fall.", "Check the position: a dip occurs early in a test and recharge only ever occurs late.", "Wait: a dip recovers to a plateau, and recharge does not.", "Compare against the semilog line, which bends for recharge and stays straight for a dip."]'::jsonb, 2, 'Mechanically the classifier makes the same false positive on both, because a steep fall lands in the recharge band. Physically the confusion is more forgivable than usual: both mean something started supplying fluid.'),
  ('welltest', 'intermediate', 'module', 'm05-heterogeneity-and-data', 8, 'Why is the dip ratio not equal to omega?', '["Because omega is defined at reservoir conditions and the dip is measured at wellbore conditions.", "Because the dip ratio is a ratio of derivatives and omega is a ratio of storage capacities, which differ by the compressibility.", "Because the classical relationship holds only for the transient-slab model, not for Warren and Root.", "Because storage, the Bourdet window and the transfer function''s own shape between them fill the dip in."]'::jsonb, 3, 'On this fixture the ratio is more than three times omega. It is a diagnostic that dual porosity is present, and a poor estimator of the parameter.'),
  ('welltest', 'intermediate', 'module', 'm05-heterogeneity-and-data', 9, 'What actually recovers omega and lambda properly?', '["A model fit, which uses the whole curve rather than two features of it.", "A longer test, which lets the dip develop fully and reach its theoretical depth.", "A downhole shut-in, which removes the storage that fills the dip in.", "A second test at a different rate, which separates the two parameters by superposition."]'::jsonb, 0, 'The features on a derivative plot are for DIAGNOSIS. Getting the parameters out is a fitting problem, and the features serve as a starting guess.'),
  ('welltest', 'intermediate', 'module', 'm05-heterogeneity-and-data', 10, 'Why does a gauge sampling at constant time intervals bias a least squares fit?', '["Because a constant interval undersamples the early data, where the pressure changes fastest.", "Because uniform spacing in time puts almost all the points in the last decade of a log axis.", "Because the noise is correlated between adjacent samples, which violates the least squares assumption.", "Because the gauge''s own response time is comparable to the interval at early times."]'::jsonb, 1, 'A test spanning four decades sampled every second has nine tenths of its points in the last decade. The early data, which carry the diagnostic information, contribute almost nothing to the fit.'),
  ('welltest', 'intermediate', 'module', 'm05-heterogeneity-and-data', 11, 'What does logDecimate do?', '["Averages the points within each logarithmic bin, which also reduces the noise.", "Removes points whose pressure change is smaller than the gauge resolution.", "Selects points that are roughly uniformly spaced in the logarithm of elapsed time.", "Interpolates the record onto a fixed logarithmic grid so that tests can be compared."]'::jsonb, 2, 'It SELECTS rather than combines. A point kept carries whatever noise it had, and smoothing is left to the Bourdet window where it is explicit and controllable.'),
  ('welltest', 'intermediate', 'module', 'm05-heterogeneity-and-data', 12, 'What is the usual decimation density for a diagnostic plot?', '["One point per decade, since a straight line needs only two points to be defined.", "As many as the gauge recorded, since decimation discards information irreversibly.", "About 100 per decade, which is fine enough to preserve every real feature of the response.", "Between about 5 and 20 points per decade, with 10 a common choice."]'::jsonb, 3, 'Too few and the derivative cannot resolve a feature. Too many and the noise is not reduced, since decimation is also a noise-reduction step.'),
  ('welltest', 'intermediate', 'module', 'm05-heterogeneity-and-data', 13, 'What is the correct order of data preparation?', '["Despike, then decimate, then differentiate.", "Decimate, then despike, then differentiate, since despiking is cheaper on fewer points.", "Differentiate, then despike the derivative, since that is where the spikes are visible.", "Decimate, then differentiate, then despike the result, which removes any remaining artefacts."]'::jsonb, 0, 'Despiking after decimation is much less effective, because the spike may be one of the few points kept and its neighbours are now far away.'),
  ('welltest', 'intermediate', 'module', 'm05-heterogeneity-and-data', 14, 'One point in 45 multiplied by 1.6 moves the Bourdet derivative by how much?', '["By about 60 percent at that point only, since the derivative is a local quantity.", "By up to 988 percent at the neighbouring points, while the pressure plot barely moves.", "By about 6 percent overall, since the Bourdet smoothing spreads the error across the window.", "Not at all, because the despiking filter removes it before the derivative is computed."]'::jsonb, 1, 'The despiker does remove it, if you run it. Left in, one bad value contaminates a neighbourhood and each contaminated estimate divides the error by a fraction of a cycle.'),
  ('welltest', 'intermediate', 'module', 'm05-heterogeneity-and-data', 15, 'Why does trimSpikes use a median rather than a mean?', '["Because a median is faster to compute over a rolling window than a mean and variance.", "Because the pressure distribution in a well test is skewed rather than normal.", "Because a mean and a standard deviation are both dragged around by the outlier they are meant to detect.", "Because a median filter also removes the drift that a mean filter would leave behind."]'::jsonb, 2, 'A single bad value in a window of five moves the median hardly at all, so the outlier is measured against a statistic it did not corrupt. Drift and steps are what no data filter catches.'),
  ('welltest', 'intermediate', 'module', 'm06-the-professional-reading', 1, 'Stated in one sentence, what does this tier add to the Associate one?', '["A more accurate measurement, since the derivative plateau gives a better permeability than a fitted line.", "The diagnosis, without which a straight-line measurement is a number attached to an unidentified regime.", "The ability to analyse boundaries, which the straight-line methods cannot represent at all.", "A model catalog, which replaces the straight lines with analytical solutions."]'::jsonb, 1, 'The model catalog and its regression are the Expert tier. Every failure in the Associate tier was a diagnosis failure rather than an arithmetic one.'),
  ('welltest', 'intermediate', 'module', 'm06-the-professional-reading', 2, 'How many false labels do the classifier''s two transition rules remove across the seven fixtures?', '["Two, one of each mechanism, since the rest were already correct before the rules existed.", "Eight, leaving one that ordering cannot reach.", "All of them, which is why a regime label can now be read as a diagnosis.", "None on these fixtures; the rules exist for reservoirs this course does not contain."]'::jsonb, 1, 'Six of the seven fixtures carried at least one, including the plain infinite-acting drawdown. The one left is the fault fixture''s first segment, where linear flow and a storage roll-off cannot be told apart by order.'),
  ('welltest', 'intermediate', 'module', 'm06-the-professional-reading', 3, 'Which value should a plateau on the buildup be compared against?', '["21.520588235294117 psi, which is the semilog slope for the same reservoir.", "70.6 psi, which is the constant in the plateau equation.", "9.344117647058821 psi, which is the theoretical plateau at the planted permeability.", "The plateau from the drawdown fixture, since the two tests share a reservoir and should agree exactly."]'::jsonb, 2, 'The two fixtures do share a reservoir and they do not agree exactly, because each had to get past a different amount of transition before radial flow began.'),
  ('welltest', 'intermediate', 'module', 'm06-the-professional-reading', 4, 'What does the fault fixture''s early semilog window give?', '["About half that, which is what the doubled late line reports instead.", "Exactly 85 mD, since the early window is before any boundary has been felt.", "26.266915078269914 mD, which is what a semilog fit on the wrong regime returns.", "81.25445414895721 mD against a planted 85 mD, which is a well diagnosed window."]'::jsonb, 3, 'A few percent low, from the residual storage transition, which is the same small bias as everywhere else in the course.'),
  ('welltest', 'intermediate', 'module', 'm06-the-professional-reading', 5, 'What is the capstone''s derivative smoothing setting?', '["L equal to zero, so that no smoothing is applied to the noise-free fixtures.", "L equal to 0.1, the engine''s default, on every field that uses a derivative.", "L equal to 0.2, which is the value that gives the cleanest dip on the dual-porosity test.", "It is chosen by the learner, since the capstone grades the method rather than a setting."]'::jsonb, 1, 'The settings are stated because these are not settings-independent quantities. The dip ratio in particular moves with L, as the module 1 sweep showed.'),
  ('welltest', 'intermediate', 'module', 'm06-the-professional-reading', 6, 'Why does the capstone state the fault windows rather than letting you choose them?', '["So that everybody''s slope ratio is the same number and the tolerance means something.", "Because the derivative on the fault fixture is too noisy to select a window reliably.", "Because the correct windows cannot be determined from the derivative on that fixture.", "Because the classifier''s segment boundaries are the windows, and they are fixed by the engine."]'::jsonb, 0, 'In practice you choose them from the derivative and defend the choice. Here they are given so that the six answers are comparable.'),
  ('welltest', 'intermediate', 'module', 'm06-the-professional-reading', 7, 'Which capstone field is a ratio rather than a reservoir property?', '["The radial plateau, which is a ratio of the pressure change to the logarithm of time.", "The drainage area, which is a ratio of the pore volume to the porosity and thickness.", "The fault slope ratio, which is evidence for a boundary rather than a rock property.", "The sqrt-time slope, which is a ratio of pressure change to the square root of time."]'::jsonb, 2, 'The late permeability is what a careless analyst would report as the answer. The ratio is dimensionless and it is what tells you a boundary is there at all.'),
  ('welltest', 'intermediate', 'module', 'm06-the-professional-reading', 8, 'The rectangle''s graded area is in square feet, not acres. Why does that matter here?', '["Because acres are not an SI unit and the grading service works only in oilfield units.", "Because the area in acres would collide with another graded field''s value and tolerance.", "Because the pore volume equation returns cubic feet, and converting twice introduces error.", "Because the tolerance is two parts in a hundred thousand, so the conversion must be exact."]'::jsonb, 3, 'Reporting the planted 2,800,000 square feet fails, correctly, because the recovered value is not the planted one and the difference is larger than the tolerance.'),
  ('welltest', 'intermediate', 'module', 'm06-the-professional-reading', 9, 'In what order does the capstone suggest working?', '["The plateau first, because it connects back to the buildup you already analysed at the previous tier.", "The drainage area first, because it is the most accurate and it establishes confidence in the method.", "The fault pair first, because they are two fields from one fixture and share their setup.", "The dip ratio first, because it is the only field that uses the derivative directly."]'::jsonb, 0, 'Its height should imply a permeability close to the one reported at the Associate tier. Then the fault pair together, then the fracture, the rectangle and the dip.'),
  ('welltest', 'intermediate', 'module', 'm06-the-professional-reading', 10, 'Which of these is a boundary diagnosis rather than a well diagnosis?', '["A half slope occurring before a radial plateau, which is linear flow towards a fracture face.", "A half slope occurring after a radial plateau.", "A quarter slope early in the test, which is bilinear flow along a finite-conductivity fracture.", "A derivative dip that recovers to the level it left, which is the dual-porosity signature."]'::jsonb, 1, 'After the plateau, the planes the fluid is moving towards are the channel walls. Before it, they are the fracture faces.'),
  ('welltest', 'intermediate', 'module', 'm06-the-professional-reading', 11, 'What did this tier show about the direction of error when a regime is misdiagnosed?', '["All three cases understate permeability and overstate stimulation, which makes the bias systematic.", "All three of the cases overstate permeability, since a mis-specified analysis always flatters the reservoir.", "Two of the three cases understate permeability and overstate stimulation; the fracture case does the reverse.", "The direction is random, which is why no rule of thumb can substitute for the derivative."]'::jsonb, 2, 'Storage and the sealing fault both give a lower permeability and a smaller skin. A fractured well read as radial gives a permeability five times too high and a strongly negative skin.'),
  ('welltest', 'intermediate', 'module', 'm06-the-professional-reading', 12, 'What is the four-line diagnosis entry this tier recommends for each regime claimed?', '["The interval, the fitted slope, the r squared of the segment, and the number of points in it.", "The regime name, the model that it implies, the parameters it gives, and their confidence intervals.", "The start time, the end time, the derivative level, and the permeability that level implies.", "The interval, the evidence, what the level implies numerically, and why the regime is possible there."]'::jsonb, 3, 'Most reports contain none of the four, and a report containing all four can be checked by somebody else, which is the whole point.'),
  ('welltest', 'intermediate', 'module', 'm06-the-professional-reading', 13, 'What is a learner at this level still unable to do?', '["Extract a model''s parameters properly, because features give diagnoses and fitting gives parameters.", "Recognise a dual-porosity response, which requires the model catalog to confirm.", "Analyse a buildup at all, since the derivative on a buildup needs the Agarwal transform introduced later.", "Compute a drainage area, which needs the closed-rectangle model rather than a Cartesian fit."]'::jsonb, 0, 'Nor has this tier met a rate history with more than one change, a gas well, or a well analysed entirely from production data.'),
  ('welltest', 'intermediate', 'module', 'm06-the-professional-reading', 14, 'Which is the correct summary of what the closed rectangle taught?', '["That a closed reservoir is the only geometry a well test can determine unambiguously.", "That once a boundary is reached, the late Cartesian line measures a volume.", "That drainage area is the most reliable quantity a well test produces on any reservoir.", "That pseudo-steady state removes the need to know the total compressibility."]'::jsonb, 1, 'It needs the compressibility badly, and that is its largest uncertainty. What it does not need is an extrapolation, which is why the arithmetic is so accurate.'),
  ('welltest', 'intermediate', 'module', 'm06-the-professional-reading', 15, 'What should you do BEFORE writing any number in an interpretation?', '["Fit the semilog line, since the permeability is needed for every other quantity.", "Compute the storage coefficient from the unit slope, which bounds the usable window.", "Write down the regime sequence: interval, slope, level and the ordering argument.", "Check the rate record against the pressure record for consistency."]'::jsonb, 2, 'Checking the rate record is worth doing and it belongs even earlier. If you cannot write the four lines for a regime, you have not diagnosed it.'),
  ('welltest', 'intermediate', 'final', null, 1, 'A log-log plot shows the pressure and derivative curves lying on top of each other for the first hour. What is happening?', '["The gauge is reading the same channel twice, which is a wiring fault in the tool string.", "The well is producing its own wellbore contents, and the storage coefficient can be read off directly.", "The reservoir is at steady state, so the pressure change and its rate of change are proportional.", "The derivative has been computed against the pressure rather than against time."]'::jsonb, 1, 'During pure storage the two are the same quantity. C equals q B t over 24 dp, taken anywhere on the unit slope.'),
  ('welltest', 'intermediate', 'final', null, 2, 'A derivative plot is flat from 8 to 60 hours at 4.7 psi. Rate 450 stb/d, B 1.25, mu 0.9 cp, h 45 ft. What permeability?', '["About 84 mD, which is the plateau equation evaluated with the semilog constant instead.", "About 338 mD, since the plateau is half the semilog slope and the slope goes in the equation.", "It cannot be found from a plateau; the permeability needs a fitted semilog line.", "About 169 mD, from 70.6 q B mu divided by the plateau and the thickness."]'::jsonb, 3, '70.6 times 450 times 1.25 times 0.9 is 35741, divided by 4.7 and by 45 gives about 169. The plateau height IS a permeability reading, with no fitting at all.'),
  ('welltest', 'intermediate', 'final', null, 3, 'A derivative rises steadily from 9 to 17 psi between 20 and 200 hours and flattens. What is the diagnosis?', '["A single sealing fault, still doubling, whose asymptote has not been reached by the end of the test.", "A channel, since the derivative rise is the beginning of linear flow between parallel faults.", "A dual-porosity transition, with the matrix beginning to feed the fissure system.", "A closed reservoir entering pseudo-steady state, which the flattening then confirms."]'::jsonb, 0, 'Pseudo-steady state would keep rising on a unit slope rather than flattening. A ratio approaching but not reaching 2 is the signature of one fault.'),
  ('welltest', 'intermediate', 'final', null, 4, 'The classifier reports a transition between those two plateaus. What is it telling you?', '["That the segment failed the minimum-span test and was reported for completeness only.", "That the derivative was too noisy in that interval for any slope to be estimated reliably.", "That the slope sat in a regime band but the position ruled the regime out, so the stretch is a passage.", "That two regimes overlap there, and a longer test would separate them."]'::jsonb, 2, 'Here the slope sat in the bilinear band, and bilinear flow is near-well geometry that cannot start after radial flow. The extent is still reported, because a transition is part of the response.'),
  ('welltest', 'intermediate', 'final', null, 5, 'A test shows a half slope from 0.01 to 3 hours, then a plateau. What is the well?', '["In a channel, because linear flow means the disturbance has reached two parallel boundaries.", "Fractured, because linear flow before radial flow is flow towards a fracture face.", "Horizontal, because the vertical radial period is too short to resolve on this plot.", "Damaged, because the half slope is the transition out of a low permeability damaged zone."]'::jsonb, 1, 'A horizontal well would show a plateau BEFORE the half slope, from vertical radial flow. Position in the sequence is what separates the two.'),
  ('welltest', 'intermediate', 'final', null, 6, 'A test shows a plateau, then a half slope that continues to the end. What is the reservoir?', '["Fractured, since a half slope is always the signature of linear flow towards a fracture.", "Dual porosity, with the matrix supply producing an apparent half slope during the transition.", "Bounded on one side only, which gives a half slope as the image well is felt.", "A channel, because linear flow after radial flow means the disturbance has reached two parallel boundaries."]'::jsonb, 3, 'A single sealing fault doubles the plateau. Two parallel faults give linear flow once the disturbance fills the width between them.'),
  ('welltest', 'intermediate', 'final', null, 7, 'A derivative plunges steeply at 300 hours and keeps falling. What is the first question?', '["What could be supplying pressure: an aquifer, a gas cap, an injector, or a data artefact.", "How far away the boundary is, since that is what the analysis is run to determine.", "Whether the smoothing window was large enough to suppress the noise at late time.", "Whether the classifier labelled it, since an unlabelled plunge is probably noise."]'::jsonb, 0, 'The diagnosis is what changes decisions. A well with pressure support keeps producing at a rate a depletion forecast does not predict; a well without it declines.'),
  ('welltest', 'intermediate', 'final', null, 8, 'A Cartesian plot of pressure against time is straight over the last eight points at 0.48 psi per hour. Rate 450 stb/d, B 1.25, ct 1.2e-5. What follows?', '["A permeability, since the Cartesian slope is proportional to flow capacity in pseudo-steady state.", "A drainage radius of about 940 ft, which follows from the slope without needing the porosity.", "A pore volume of about 22.8 million cubic feet, from 0.23396 q B divided by ct and the slope.", "Nothing yet, because a Cartesian straight line also occurs during wellbore storage."]'::jsonb, 2, 'A Cartesian line during storage would be at the very start of the test rather than the end. The pore volume equation has no permeability, skin or geometry in it.'),
  ('welltest', 'intermediate', 'final', null, 9, 'Why is a drainage volume from pseudo-steady state more accurate than a permeability from a semilog line?', '["Because the Cartesian fit uses more points than a semilog window normally contains.", "Because it is an equilibrium rather than an asymptote that is still being approached.", "Because the compressibility is known more precisely than the net pay in most reservoirs.", "Because it does not require the rate to be constant, which the semilog analysis does."]'::jsonb, 1, 'It very much requires a constant rate. What it does not require is an extrapolation, and that is where the accuracy comes from.'),
  ('welltest', 'intermediate', 'final', null, 10, 'A drainage area is reported without the total compressibility used. What is wrong?', '["Nothing, since compressibility cancels between the pore volume and the area conversion.", "The porosity is the larger uncertainty, and that is what should have been reported instead.", "The rate matters more, since the pore volume equation is linear in it.", "The largest lever on the answer, and one entirely outside the test, has been left out."]'::jsonb, 3, 'A ct 20 percent high gives a pore volume 17 percent low, from data that fit the line exactly as well. There is no signature in the fit.'),
  ('welltest', 'intermediate', 'final', null, 11, 'A dip in the derivative recovers to the level it left. What is that?', '["Dual porosity, because the matrix has fed the fissures and the two systems have reached equilibrium.", "A constant-pressure boundary being felt and then exhausted as the aquifer depletes.", "A rate change during the test, which produces a transient dip in the rate-normalised response.", "Over-smoothing across a short radial plateau, which produces an apparent dip either side of it."]'::jsonb, 0, 'Recharge does not recover: it keeps supplying and the derivative keeps falling. Waiting is how you tell them apart.'),
  ('welltest', 'intermediate', 'final', null, 12, 'A dip ratio of 0.28 is measured on a reservoir whose omega is 0.08. What went wrong?', '["The derivative was computed against the wrong time variable, which distorts the dip depth.", "The smoothing window was too small, so the dip was under-resolved and reported too shallow.", "Nothing: the dip ratio is a diagnostic that dual porosity is present rather than a value of omega.", "The late plateau was averaged over a window that had not yet reached total-system radial flow."]'::jsonb, 2, 'Storage, the Bourdet window and the transfer function''s own shape all fill the dip in. Recovering omega properly needs a model fit.'),
  ('welltest', 'intermediate', 'final', null, 13, 'A gauge samples every second for three days and the analysis fits a semilog line to all of it. What is the hidden problem?', '["The dataset is too large for a least squares fit to converge without numerical error.", "Nine tenths of the points sit in the last decade, so the fit is dominated by the late data.", "The gauge noise is correlated between adjacent samples, which biases the fitted slope.", "The pressure changes between samples are below the gauge resolution, so most points are identical."]'::jsonb, 1, 'Uniform spacing in time is extremely non-uniform on a logarithmic axis. Log decimation to about ten points per decade fixes the weighting.'),
  ('welltest', 'intermediate', 'final', null, 14, 'You decimate a record to 6 points per decade and the dual-porosity dip disappears. What happened?', '["The dip spans too little of a decade to survive at that density, and the decimation was too aggressive.", "The decimation averaged the points within each bin, which flattened the feature.", "The dip was an artefact of the sampling and the decimation correctly removed it.", "The derivative now has too few points for the Bourdet rule to find neighbours a full window away."]'::jsonb, 0, 'logDecimate selects rather than averages. Between 5 and 20 points per decade is the usual range and a short feature needs the upper end of it.'),
  ('welltest', 'intermediate', 'final', null, 15, 'A derivative plot is smooth except for one wild excursion at 0.7 hours. What is the most likely cause?', '["A rate change at that time that was not recorded in the production report.", "The transition out of wellbore storage, which produces a local maximum in the derivative.", "The Bourdet window straddling a change in sampling interval at that point.", "A single bad pressure reading, which a rolling median filter will remove."]'::jsonb, 3, 'One point multiplied by 1.6 in the drawdown fixture moves the derivative by nearly a thousand percent at its neighbours, while the pressure plot barely changes.'),
  ('welltest', 'intermediate', 'final', null, 16, 'Why does the despiking filter use a median absolute deviation rather than a standard deviation?', '["Because the pressure residuals are not normally distributed in a well test.", "Because a standard deviation is inflated by the outlier it is supposed to detect.", "Because the median absolute deviation is faster to compute over a rolling window.", "Because a standard deviation requires more points than a five-point window provides."]'::jsonb, 1, 'A single bad value in a window of five moves the median hardly at all, so the outlier is measured against a statistic it did not corrupt.'),
  ('welltest', 'intermediate', 'final', null, 17, 'Which data problem will NO filter catch?', '["A single spike of 60 percent in one pressure reading among 45 points.", "A cluster of three bad readings in succession near the end of a record.", "A gauge drifting slowly upward through the test.", "A pressure reading recorded as zero because of a telemetry dropout."]'::jsonb, 2, 'A drift is not an outlier at any point. It looks like reservoir behaviour and it is one of the hardest problems in real test analysis, along with steps and unrecorded rate changes.'),
  ('welltest', 'intermediate', 'final', null, 18, 'A fractured well''s sqrt-time line is fitted over a window that runs past linear flow. Which way is the half-length wrong?', '["Too long, because including the flatter transition lowers the fitted slope.", "Too short, because the transition data pull the line steeper than pure linear flow.", "Unbiased, because the least squares fit averages the two regimes symmetrically.", "It depends on the permeability assumed, which is the only quantity the window affects."]'::jsonb, 0, 'Half-length is inversely proportional to the slope. On the fixture, a fit to 10 hours gives a half-length about 14 percent above the planted 250 ft.'),
  ('welltest', 'intermediate', 'final', null, 19, 'A fractured well analysed with a semilog line reports 26 mD in rock that is 5 mD. Where did the extra factor come from?', '["From the storage transient, which flattens the early semilog line and raises the permeability.", "From the fracture, whose contribution was absorbed into an inflated permeability and a negative skin.", "From the thickness, which for a fractured well should be the fracture height and not the net pay at all.", "From the rate, since a fractured well''s measured rate includes the fracture''s own drainage."]'::jsonb, 1, 'The analysis distributed one physical effect between two parameters that cannot represent it. Both errors flatter the well.'),
  ('welltest', 'intermediate', 'final', null, 20, 'What would you need to split a fracture''s xf times root k product?', '["A longer sqrt-time window, which constrains the two parameters separately.", "A second test at a different rate, which breaks the degeneracy by superposition.", "The fracture conductivity, which the bilinear flow period provides.", "A permeability from radial flow, a core, or a nearby well."]'::jsonb, 3, 'Halve the permeability and adjust the half-length and the response is identical. Only a different regime or a different measurement resolves it.'),
  ('welltest', 'intermediate', 'final', null, 21, 'A horizontal well shows a plateau, then a half slope, then a second plateau at a different level. What are the two plateaus?', '["Fissure system radial flow and then total system radial flow, which is dual porosity.", "Radial flow before and after a sealing fault, whose image well doubles the second of them.", "Vertical radial flow around the lateral, then pseudoradial flow in the horizontal plane.", "Radial flow and then a boundary-affected plateau at the reduced drainage area."]'::jsonb, 2, 'The first involves the geometric mean of horizontal and vertical permeability with the well length; the second is ordinary horizontal permeability with the layer thickness.'),
  ('welltest', 'intermediate', 'final', null, 22, 'A lateral''s first plateau is fitted with the standard slope equation. What is the resulting number?', '["Meaningless, because the quantity the equation computes is not the quantity it defines.", "Because the early data are always dominated by wellbore storage in a long lateral.", "Because the vertical permeability is unknown, and the early plateau depends on it.", "Because horizontal wells are usually completed openhole, so the wellbore radius is undefined."]'::jsonb, 0, 'The early plateau involves the well length and the anisotropy rather than the layer thickness the equation assumes. The number is meaningless rather than merely imprecise.'),
  ('welltest', 'intermediate', 'final', null, 23, 'A well test is diagnosed as a sealing fault and a semilog line is fitted after it. What should the report say?', '["The late line''s permeability, doubled, since a single fault doubles the true slope exactly.", "The early line''s permeability, with the slope ratio as the evidence for the boundary.", "The average of the two lines, since both are valid analyses of the same well.", "The late line''s permeability as reported, since the late data are free of storage."]'::jsonb, 1, 'Doubling the late line is a legitimate correction under a single-fault assumption, and knowing it is a single fault is the thing you were trying to establish.'),
  ('welltest', 'intermediate', 'final', null, 24, 'Where is the semilog line on a test that shows storage, a hump, a plateau and then a rise?', '["Anywhere after the hump, since the rise is a boundary effect the line can be extrapolated through.", "Across the whole record, since a least squares fit weights the regimes according to their extent.", "In the hump, since that is where the near-well information about the skin lives.", "Between the end of the hump and the start of the rise."]'::jsonb, 3, 'Bounded at both ends by physics: after the storage transition, before the first boundary. That is the window justification the Associate tier could not produce.'),
  ('welltest', 'intermediate', 'final', null, 25, 'How would you decide whether a derivative feature is real or an artefact of the smoothing?', '["Compare it against the model catalog, since only shapes the models produce can be real.", "Recompute it with a different derivative algorithm and keep what both agree on.", "Sweep the smoothing window: a real feature barely moves, and one that appears or vanishes is not real.", "Check whether the classifier labelled it, since an unlabelled feature is probably noise."]'::jsonb, 2, 'On clean data the whole L range moves the answer by less than three tenths of a percent, so any sensitivity on real data is telling you about the noise.'),
  ('welltest', 'intermediate', 'final', null, 26, 'The buildup''s derivative plateau sits slightly ABOVE the theoretical value at 85 mD. Why?', '["Because the transition out of storage has not entirely finished by the end of the test.", "Because the buildup''s derivative is computed against equivalent time, which compresses the late data.", "Because the plateau is averaged over a window that includes part of the transition deliberately.", "Because the theoretical value assumes zero skin, and this well has a skin of plus 6.5."]'::jsonb, 0, 'So a permeability read off the plateau is slightly low, in the same direction and for the same reason as the semilog answer. They share the cause but not the magnitude.'),
  ('welltest', 'intermediate', 'final', null, 27, 'Which regime label would you distrust immediately if it appeared FIRST in a sequence?', '["Wellbore storage, because a downhole shut-in should remove it entirely.", "Constant-pressure boundary, because recharge cannot precede radial flow.", "Linear flow, because a fracture''s linear flow is always preceded by bilinear flow.", "Radial flow, because storage always comes first in any real test."]'::jsonb, 1, 'A fracture with infinite conductivity gives linear flow with no bilinear period at all, so linear flow first is perfectly possible. An aquifer already felt would have held the pressure up from the start.'),
  ('welltest', 'intermediate', 'final', null, 28, 'You are handed a derivative plot with coloured regime bands and a list of labels. What has been done for you?', '["A full diagnosis, which the model fit will then quantify.", "A comparison against the model catalog, selecting the model whose shape matches best.", "A statistical test of each candidate regime against the noise level in the data.", "A slope classification, a minimum-span filter and three ordering rules, and nothing about the levels."]'::jsonb, 3, 'Three conditions, all necessary, none of them about the LEVEL a segment sits at or about whether the pressure curve agrees. Those two checks are still yours.'),
  ('welltest', 'intermediate', 'final', null, 29, 'Two diagnoses both fit the derivative equally well. What belongs in the report?', '["Both, with what each would imply and what measurement would separate them.", "The simpler one, since a model with fewer parameters is preferred when both fit.", "The one that agrees with the geological model, which is the independent evidence available.", "Neither, since an ambiguous diagnosis cannot support a quantitative result at all."]'::jsonb, 0, 'Reporting a single answer where the data support two is not confidence, it is a suppressed result, and the reader is the one making the decision.'),
  ('welltest', 'intermediate', 'final', null, 30, 'A test in a field mapped at 40 mD shows a plateau implying 900 mD. What is the most useful response?', '["Report it, since a well test measures a larger volume than a map and should override it.", "Discard the test, since a discrepancy of that size means the data are unusable.", "Treat the number as evidence about the analysis before treating it as evidence about the reservoir.", "Adjust the thickness until the permeability matches the map, since h is the least certain input of all."]'::jsonb, 2, 'An improbable result has, far more often, been run on the wrong flow regime. The burden is on the interpretation to show which.'),
  ('welltest', 'intermediate', 'final', null, 31, 'What does a unit slope at the very end of a long test most likely mean?', '["Wellbore storage returning, which happens when the rising liquid level reaches a change of tubing size.", "Pseudo-steady state, if the derivative has been rising towards it rather than through a transition.", "A gauge failure, since a unit slope at late time is not a physically realisable regime.", "A second sealing fault, since each fault adds an image well and steepens the response."]'::jsonb, 1, 'On a short test a late unit slope can be the beginning of a transition rather than established pseudo-steady state, in which case the volume read off it is too small.'),
  ('welltest', 'intermediate', 'final', null, 32, 'Why does the engine''s classifier discard segments shorter than a quarter of a decade?', '["Because a shorter segment cannot contain enough points for the slope estimate to be stable.", "Because the Bourdet smoothing window spans a quarter decade at the default setting.", "Because regimes shorter than that are not physically meaningful in a radial system.", "To stop noise generating segments, at the cost of hiding a real but short regime."]'::jsonb, 3, 'On the fracture fixture, radial flow is reported over exactly 0.25 decades at the very end. A slightly shorter test would have reported no radial flow at all on the same well.'),
  ('welltest', 'intermediate', 'final', null, 33, 'What is the practical consequence of the derivative amplifying noise?', '["Data preparation stops being optional and has to happen before any interpretation.", "The derivative can only be used qualitatively, with the quantitative work done on the pressure.", "Real tests need gauges an order of magnitude more precise than a semilog analysis requires.", "The Bourdet window must be set from the noise level, which has to be measured first."]'::jsonb, 0, 'Despike, then decimate, then differentiate. Judging data quality from a pressure plot and then interpreting a derivative is judging the wrong thing.'),
  ('welltest', 'intermediate', 'final', null, 34, 'A dual-porosity fit is wanted but the test stopped before the derivative recovered. What can be said?', '["That the reservoir is dual porosity, with omega estimated from the dip depth alone.", "That the reservoir is not dual porosity, since a recovery is required for the diagnosis.", "That the reservoir may be dual porosity, and that the test does not establish it.", "That the derivative fall is a constant-pressure boundary, since it did not recover."]'::jsonb, 2, 'A dip that has not recovered is consistent with dual porosity and with recharge. The honest report names both and says what would separate them.'),
  ('welltest', 'intermediate', 'final', null, 35, 'Which pair of quantities does a sealing fault let you report that a plateau alone does not?', '["The storage coefficient and the skin, both of which the boundary constrains.", "The slope ratio between the two lines, and the distance the fault sits at.", "The drainage area and the pore volume, since a fault bounds the drainage region.", "The vertical and horizontal permeability, which the image well separates."]'::jsonb, 1, 'The distance comes from the intersection of the two semilog lines classically, or from a model fit. The ratio is the evidence that a boundary is there at all.'),
  ('welltest', 'intermediate', 'final', null, 36, 'What is the derivative level of a well between two parallel faults doing at very late time?', '["Rising on a unit slope, because a channel is bounded and reaches pseudo-steady state.", "Flat at four times the early plateau, since each fault contributes a doubling.", "Falling, because the two faults reflect the pressure disturbance back towards the well.", "Rising on a half slope, because the flow has become one dimensional along the channel."]'::jsonb, 3, 'A channel is bounded in one direction only, so it never reaches pseudo-steady state. Linear flow along it continues indefinitely.'),
  ('welltest', 'intermediate', 'final', null, 37, 'A well test is diagnosed correctly and the semilog window chosen from the derivative. How accurate is the permeability?', '["A few percent, because the window still contains a trace of the transition it followed.", "Exact, since a correctly diagnosed window contains only radial flow by construction.", "Within about twenty percent, which is the accuracy a semilog analysis is capable of.", "It depends entirely on the gauge, since with a correct window there is no other error source."]'::jsonb, 0, 'Convergence towards the truth is not arrival at it. That bias is inherent in an asymptotic method, and only a model fit removes it.'),
  ('welltest', 'intermediate', 'final', null, 38, 'Which of these does the derivative NOT help with?', '["Locating the interval over which a semilog line should be fitted.", "Distinguishing a fractured well from a damaged one in an infinite-acting reservoir.", "Deciding whether the rate record is correct.", "Recognising that a test never reached radial flow at all."]'::jsonb, 2, 'A wrong rate produces a self-consistent pressure response of the wrong magnitude. No shape-based diagnostic finds it; only the rate record does.'),
  ('welltest', 'intermediate', 'final', null, 39, 'A test report claims a fault at 640 ft. What is the minimum evidence you would expect to see?', '["A semilog plot with two straight lines and the time at which they intersect.", "A derivative showing a rise from one plateau towards a higher one, with both levels stated.", "A model fit with a converged flag and a confidence interval on the distance.", "A geological map showing a fault at approximately that distance from the well."]'::jsonb, 1, 'The map is corroboration and it is worth having. The pressure evidence is the doubling in progress, and without it the distance came from a parameter nothing constrained.'),
  ('welltest', 'intermediate', 'final', null, 40, 'What is the single most useful thing to do before interpreting any pressure history?', '["Plot the derivative and read it as a data-quality check rather than as a result.", "Fit a semilog line to the whole record to establish the order of magnitude.", "Compute the equivalent producing time from the rate record before anything else.", "Compare the total pressure change against the expected drawdown for the mapped permeability."]'::jsonb, 0, 'Scatter growing towards late time is normal. Isolated excursions are spikes, and a stretch that is wild where the rest is smooth is usually a data problem in that stretch.'),
  ('welltest', 'intermediate', 'final', null, 41, 'A test''s derivative is flat, then falls steeply, then flattens again at the same level. What is it?', '["A sealing fault, since the derivative returns to a plateau after the boundary is felt.", "A rate change mid test, which produces a transient fall and recovery in the response.", "Dual porosity, whose two plateaus sit at the same height because the permeability never changed.", "A gauge that was replaced during the test, which shifts the record and then restores it."]'::jsonb, 2, 'Two plateaus at the same height with a dip between them is the signature, and nothing else in well testing looks like it.'),
  ('welltest', 'intermediate', 'final', null, 42, 'Why is the closed rectangle the only fixture in this course whose answer comes out right?', '["Because it is the only fixture with no wellbore storage in it to contaminate the early data.", "Because its analysis uses a Cartesian rather than a logarithmic axis, which is numerically better conditioned.", "Because its four boundary distances were chosen to make the transition short.", "Because pseudo-steady state is an identity rather than an asymptote, so there is nothing to converge towards."]'::jsonb, 3, 'Every other number in this course is an extrapolation. That one is a measurement, and it is accurate to a few thousandths of a percent.');
